package reflectcore

import (
	"os"
	"path/filepath"
	"reflect"
	"regexp"
	"runtime"
	"strings"
)

// The types whose layout a Go model changes, opaque to reflection: go.layoutModelled
// (Perennial/Golang/Defn/LayoutModelled.lean, generated by goose).

// layoutModelledNames is go.layoutModelledNames, read from the generated Lean file.
var layoutModelledNames = readLayoutModelledNames()

func readLayoutModelledNames() map[string]bool {
	_, file, _, _ := runtime.Caller(0)
	path := filepath.Join(filepath.Dir(file), "../../../../..", "Perennial/Golang/Defn/LayoutModelled.lean")
	src, err := os.ReadFile(path)
	if err != nil {
		panic("harness: " + err.Error())
	}
	names := make(map[string]bool)
	for _, m := range regexp.MustCompile(`go!"([^"]*)"`).FindAllStringSubmatch(string(src), -1) {
		names[m[1]] = true
	}
	if !names["reflect.rtype"] || !names["internal/reflectlite.rtype"] {
		panic("harness: " + path + " lacks the models' rtypes")
	}
	return names
}

// harnessPkgs maps the harness's copies of the model packages (gen.sh) to the packages they model.
var harnessPkgs = map[string]string{
	"github.com/mit-pdos/perennial/goose/model/reflect/harness/reflectmodel":     "reflect",
	"github.com/mit-pdos/perennial/goose/model/reflect/harness/reflectlitemodel": "internal/reflectlite",
}

// ExtraLayoutModelled are the types a test declares layoutModelled: types it treats as ones a
// model redefines (a redefined sync.Mutex).
var ExtraLayoutModelled = map[reflect.Type]bool{}

// LayoutModelled is go.layoutModelled: T is a named type (with any type arguments) of
// layoutModelledNames, or of ExtraLayoutModelled.
func LayoutModelled(T reflect.Type) bool {
	if ExtraLayoutModelled[T] {
		return true
	}
	name := T.Name()
	if name == "" {
		return false
	}
	if i := strings.IndexByte(name, '['); i >= 0 {
		name = name[:i]
	}
	pkg := T.PkgPath()
	if p, ok := harnessPkgs[pkg]; ok {
		pkg = p
	}
	return layoutModelledNames[pkg+"."+name]
}

// ConvertExposed is go.convertExposed: T is LayoutModelled, or a pointer type whose base type is.
func ConvertExposed(T reflect.Type) bool {
	return LayoutModelled(T) || T.Kind() == reflect.Pointer && LayoutModelled(T.Elem())
}
